// Lunar New Year pricing card: red lacquer and gold leaf, a stepped deco frame, scroll-cloud corners, a round lantern medallion behind the price and a gold foil CTA.
export const meta = {
  title: "Lantern Fortune Tier",
  kind: "ui",
  description: "A Lunar New Year pricing card in red lacquer and gold leaf. It has a stepped deco frame, auspicious cloud corners, a lantern medallion behind the price and a foil button, for festive promotions, holiday memberships and seasonal premium tiers.",
  tags: ["lunar new year", "pricing card", "chinese new year", "red and gold", "lantern", "festive", "art deco", "ui"],
  price: 8,
  author: "Pat Liu",
  size: [480, 640],
};

export const params = {
  knobs: {
    gold: { type: "color", label: "Gold leaf", default: "#E2B65A" },
    ground: { type: "color", label: "Lacquer", default: "#9E1B1B" },
    backdrop: { type: "color", label: "Backdrop", default: "#3A0808" },
    frame: { type: "choice", label: "Frame style", default: "stepped", options: ["stepped", "double line", "chevron"] },
    period: { type: "choice", label: "Billing period", default: "year", options: ["month", "year", "user / month"] },
    plan: { type: "text", label: "Plan name", default: "Golden Dragon" },
    price: { type: "text", label: "Price", default: "$88" },
    features: { type: "range", label: "Feature rows", default: 5, min: 3, max: 6, step: 1 },
    ribs: { type: "range", label: "Lantern ribs", default: 10, min: 4, max: 16, step: 2 },
    popular: { type: "toggle", label: "Lucky pick badge", default: true },
  },
  presets: {
    "Imperial Lacquer": { gold: "#E2B65A", ground: "#9E1B1B", backdrop: "#3A0808" },
    "Cinnabar Night": { gold: "#F0C46A", ground: "#5E0F14", backdrop: "#14070A" },
    "Jade Palace": { gold: "#DDBB66", ground: "#0F4A3A", backdrop: "#061F18" },
    "Rice Paper": { gold: "#B0322A", ground: "#F7EEDC", backdrop: "#E6D3B0" },
  },
};

const FEATURES = [
  "Red envelope rewards",
  "Priority banquet seating",
  "Lantern festival access",
  "Dedicated fortune concierge",
  "Year-round prosperity perks",
  "Gold seal &amp; insignia",
];
const NOTES = {
  month: "Billed monthly · cancel anytime",
  year: "Billed yearly · first moon complimentary",
  "user / month": "Per guest · billed monthly",
};
const F = "Didot, 'Bodoni 72', 'Bodoni MT', Georgia, 'Times New Roman', serif";

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const f1 = (v) => (+v).toFixed(1);
function rgb(h) {
  const n = parseInt(String(h).slice(1, 7), 16) || 0;
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function mix(a, b, t) {
  const x = rgb(a), y = rgb(b);
  return "#" + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, "0")).join("");
}
const lum = (h) => { const [r, g, b] = rgb(h); return (0.299 * r + 0.587 * g + 0.114 * b) / 255; };
const ink = (h) => (lum(h) > 0.55 ? "#2A0C08" : "#FFF4DE");

function stepPath(x, y, w, h, s) {
  const R = x + w, B = y + h, s2 = s * 2;
  return `M${f1(x + s2)} ${y}H${f1(R - s2)}V${f1(y + s)}H${f1(R - s)}V${f1(y + s2)}H${R}V${f1(B - s2)}H${f1(R - s)}V${f1(B - s)}H${f1(R - s2)}V${B}H${f1(x + s2)}V${f1(B - s)}H${f1(x + s)}V${f1(B - s2)}H${x}V${f1(y + s2)}H${f1(x + s)}V${f1(y + s)}H${f1(x + s2)}Z`;
}
function octPath(x, y, w, h, c) {
  const R = x + w, B = y + h;
  return `M${f1(x + c)} ${y}H${f1(R - c)}L${R} ${f1(y + c)}V${f1(B - c)}L${f1(R - c)} ${B}H${f1(x + c)}L${x} ${f1(B - c)}V${f1(y + c)}Z`;
}

export default function render(p) {
  const W = 480, H = 640;
  const gold = p.gold, ground = p.ground;
  const light = lum(ground) > 0.5;
  const text = light ? "#2A1210" : "#FBEFD8";
  const muted = mix(text, ground, 0.4);
  const gInk = light ? mix(gold, "#000000", 0.12) : gold;
  const pop = !!p.popular;
  const style = p.frame;

  const n = clamp(Math.round(p.features), 3, 6);
  const nr = clamp(Math.round(p.ribs / 2) * 2, 4, 16);
  const cw = 360, cx = (W - cw) / 2;
  const rowY0 = 292, gap = 32;
  const btnY = rowY0 + (n - 1) * gap + 40;
  const ch = btnY + 100;
  const cy = Math.round((H - ch) / 2) + (pop ? 4 : 0);
  const mid = cw / 2;
  const LY = 182, LR = 62;

  const shape = (i) => {
    const x = i, y = i, w = cw - 2 * i, h = ch - 2 * i;
    if (style === "stepped") return stepPath(x, y, w, h, Math.max(4, 10 - i * 0.3));
    if (style === "chevron") return octPath(x, y, w, h, Math.max(8, 26 - i * 0.6));
    return `M${x} ${y}H${x + w}V${y + h}H${x}Z`;
  };

  const hi = mix(gold, "#FFFFFF", 0.5), lo = mix(gold, "#000000", 0.38);
  const defs = `<defs>
<linearGradient id="foil" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hi}"/><stop offset="0.38" stop-color="${gold}"/><stop offset="0.56" stop-color="${lo}"/><stop offset="0.82" stop-color="${mix(gold, "#FFFFFF", 0.25)}"/><stop offset="1" stop-color="${mix(gold, "#000000", 0.18)}"/></linearGradient>
<linearGradient id="foilD" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${mix(gInk, "#FFFFFF", light ? 0.1 : 0.4)}"/><stop offset="0.5" stop-color="${gInk}"/><stop offset="1" stop-color="${mix(gInk, "#000000", 0.25)}"/></linearGradient>
<radialGradient id="lan" gradientUnits="userSpaceOnUse" cx="${mid - 14}" cy="${LY - 18}" r="${LR * 1.3}"><stop offset="0" stop-color="${mix(gold, "#FFFFFF", 0.3)}" stop-opacity="${light ? 0.22 : 0.3}"/><stop offset="1" stop-color="${gold}" stop-opacity="${light ? 0.06 : 0.07}"/></radialGradient>
<radialGradient id="glow" gradientUnits="userSpaceOnUse" cx="${mid}" cy="${LY}" r="${LR * 2.1}"><stop offset="0.3" stop-color="${gold}" stop-opacity="${light ? 0.12 : 0.18}"/><stop offset="1" stop-color="${gold}" stop-opacity="0"/></radialGradient>
<radialGradient id="bd" gradientUnits="userSpaceOnUse" cx="${W / 2}" cy="${H / 2}" r="${H * 0.7}"><stop offset="0" stop-color="${gold}" stop-opacity="${light ? 0.14 : 0.12}"/><stop offset="1" stop-color="${gold}" stop-opacity="0"/></radialGradient>
<pattern id="coins" width="40" height="40" patternUnits="userSpaceOnUse"><g fill="none" stroke="${gold}" stroke-opacity="${light ? 0.12 : 0.07}" stroke-width="1"><circle cx="0" cy="0" r="20"/><circle cx="40" cy="0" r="20"/><circle cx="0" cy="40" r="20"/><circle cx="40" cy="40" r="20"/><circle cx="20" cy="20" r="20"/></g></pattern>
<filter id="sh" x="-30%" y="-20%" width="160%" height="150%"><feDropShadow dx="0" dy="20" stdDeviation="22" flood-color="${pop && !light ? gold : "#000000"}" flood-opacity="${light ? 0.2 : pop ? 0.22 : 0.55}"/></filter>
</defs>`;

  const bgLayer = `<rect width="${W}" height="${H}" fill="${p.backdrop}"/><rect width="${W}" height="${H}" fill="url(#coins)"/><rect width="${W}" height="${H}" fill="url(#bd)"/>`;

  let ribs = "";
  for (let i = 1; i < nr / 2; i++) {
    const rx = LR * Math.abs(Math.cos((Math.PI * i) / nr));
    ribs += `<ellipse cx="${mid}" cy="${LY}" rx="${f1(rx)}" ry="${LR}"/>`;
  }
  const lantern = `<circle cx="${mid}" cy="${LY}" r="${LR * 2.1}" fill="url(#glow)"/>
<circle cx="${mid}" cy="${LY}" r="${LR}" fill="url(#lan)"/>
<g fill="none" stroke="${gInk}" stroke-opacity="${light ? 0.32 : 0.34}" stroke-width="0.9">${ribs}<path d="M${mid} ${LY - LR}V${LY + LR}"/></g>
<circle cx="${mid}" cy="${LY}" r="${LR}" fill="none" stroke="${gInk}" stroke-opacity="0.6" stroke-width="1.1"/>
<circle cx="${mid}" cy="${LY}" r="${LR + 7}" fill="none" stroke="${gInk}" stroke-opacity="0.3" stroke-width="0.6" stroke-dasharray="1.5 4"/>
<rect x="${mid - 22}" y="${LY - LR - 5}" width="44" height="8" rx="1.5" fill="url(#foil)" fill-opacity="0.75"/>
<rect x="${mid - 22}" y="${LY + LR - 3}" width="44" height="8" rx="1.5" fill="url(#foil)" fill-opacity="0.75"/>`;

  const fc = style === "chevron" ? 30 : 26;
  const cloud = (x, y, sx, sy) =>
    `<g transform="translate(${x} ${y}) scale(${sx} ${sy})" fill="none" stroke="${gInk}" stroke-width="1.1" stroke-linecap="round"><path d="M0 22C0 10 8 3 17 5C24 7 24 16 17 17C12 18 10 13 14 11M17 5C20 -1 33 -2 36 6C38 13 31 16 28 12C26 9 29 7 31 9M36 6C41 4 47 5 50 9M0 22C-2 30 3 38 10 38C16 38 17 31 12 30C9 30 8 33 10 34M10 38C9 43 6 47 2 50"/><circle cx="4" cy="4" r="2.2" fill="${gInk}" stroke="none"/></g>`;
  const clouds = cloud(fc, fc, 1, 1) + cloud(cw - fc, fc, -1, 1) + cloud(fc, ch - fc, 1, -1) + cloud(cw - fc, ch - fc, -1, -1);

  const diamond = (x, y, s) => `<path d="M${x} ${y - s}L${x + s} ${y}L${x} ${y + s}L${x - s} ${y}Z" fill="${gInk}"/>`;
  const rule = (y, half, triple) =>
    `<path d="M${mid - half} ${y}H${mid - (triple ? 22 : 12)}M${mid + (triple ? 22 : 12)} ${y}H${mid + half}" stroke="${gInk}" stroke-width="1"/>` +
    diamond(mid, y, 4.5) + (triple ? diamond(mid - 13, y, 2.5) + diamond(mid + 13, y, 2.5) : "");

  let rows = "";
  for (let i = 0; i < n; i++) {
    const y = rowY0 + i * gap;
    rows += `<circle cx="64" cy="${y - 3}" r="6" fill="none" stroke="${gInk}" stroke-width="1.2"/><rect x="62" y="${y - 5}" width="4" height="4" fill="${gInk}"/>`;
    rows += `<text x="84" y="${y + 2}" font-size="15" fill="${text}" fill-opacity="0.94">${FEATURES[i]}</text>`;
  }

  const bx = 52, bw = cw - 104, bh = 48, c = 14;
  const btn = `<path d="M${bx + c} ${btnY}H${bx + bw - c}L${bx + bw} ${btnY + bh / 2}L${bx + bw - c} ${btnY + bh}H${bx + c}L${bx} ${btnY + bh / 2}Z" fill="url(#foil)"/>
<path d="M${bx + c + 2} ${btnY + 4}H${bx + bw - c - 2}L${bx + bw - 5} ${btnY + bh / 2}L${bx + bw - c - 2} ${btnY + bh - 4}H${bx + c + 2}L${bx + 5} ${btnY + bh / 2}Z" fill="none" stroke="${mix(gold, "#000000", 0.45)}" stroke-opacity="0.5" stroke-width="0.8"/>
<text x="${mid}" y="${btnY + 29}" text-anchor="middle" font-size="13" font-weight="700" letter-spacing="3" fill="${ink(gold)}">CLAIM YOUR FORTUNE</text>`;

  const planRaw = String(p.plan || "").slice(0, 18).toUpperCase();
  const priceRaw = String(p.price || "").slice(0, 9);
  const planFs = clamp(250 / (Math.max(1, planRaw.length) * 0.92), 14, 26);
  const priceFs = clamp(210 / (Math.max(1, priceRaw.length) * 0.6), 34, 58);
  const perLabel = "PER " + esc(String(p.period || "").toUpperCase());

  const bdgW = 150;
  const badge = pop
    ? `<g transform="translate(${mid} 0)"><path d="M${-bdgW / 2} 0L${-bdgW / 2 + 12} -13H${bdgW / 2 - 12}L${bdgW / 2} 0L${bdgW / 2 - 12} 13H${-bdgW / 2 + 12}Z" fill="url(#foil)" stroke="${ground}" stroke-width="3" paint-order="stroke"/><text x="0" y="3.8" text-anchor="middle" font-size="10" font-weight="700" letter-spacing="2.6" fill="${ink(gold)}">LUCKY PICK</text></g>`
    : "";

  const card = `<g transform="translate(${cx} ${cy})">
<path d="${shape(0)}" fill="${ground}" filter="url(#sh)"/>
${lantern}
<path d="${shape(0)}" fill="none" stroke="${gInk}" stroke-width="${pop ? 1.6 : 1}" stroke-opacity="${pop ? 1 : 0.55}"/>
<path d="${shape(12)}" fill="none" stroke="${gInk}" stroke-width="1.2"/>
<path d="${shape(style === "double line" ? 16 : 17)}" fill="none" stroke="${gInk}" stroke-width="0.6" stroke-opacity="0.6"/>
${clouds}
${rule(46, 64, false)}
<text x="${mid}" y="84" text-anchor="middle" font-size="${f1(planFs)}" font-weight="700" letter-spacing="5" fill="url(#foilD)">${esc(planRaw)}</text>
<text x="${mid}" y="106" text-anchor="middle" font-size="13" font-style="italic" fill="${muted}">Prosperity &amp; fortune for the new year</text>
<text x="${mid}" y="${f1(170 + priceFs * 0.34)}" text-anchor="middle" font-size="${f1(priceFs)}" font-weight="400" letter-spacing="-1" fill="${text}">${esc(priceRaw)}</text>
<text x="${mid}" y="${f1(196 + priceFs * 0.34)}" text-anchor="middle" font-size="11" letter-spacing="3.2" fill="${gInk}">${perLabel}</text>
<text x="${mid}" y="${f1(218 + priceFs * 0.34)}" text-anchor="middle" font-size="12" font-style="italic" fill="${muted}">${esc(NOTES[p.period] || "")}</text>
${rule(266, 108, true)}
${rows}
${btn}
<text x="${mid}" y="${btnY + 76}" text-anchor="middle" font-size="11" letter-spacing="1.6" fill="${muted}">OFFER ENDS AT THE LANTERN FESTIVAL</text>
${badge}
</g>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${defs}${bgLayer}<g font-family="${F}">${card}</g></svg>`;
}
